    '2d': {"title": "The water cycle", "mode": "2d", "layout": "the sea along the bottom, a hill on the right, the sun top right, a cloud in the middle top", "intro": "Water keeps moving between the sea, the sky and the land.", "summary": "Evaporate, condense, fall, collect, and it starts again.", "photo": "a real landscape with the sea, a hill, clouds and rain falling, on a sunny day", "parts": [{"id": "sea", "label": "Ocean", "say": "Most water is in the oceans, lakes and rivers.", "color": "#7fb0ff", "box": [10, 206, 380, 46], "shapes": [{"t": "path", "d": "M10 222 Q60 210 110 222 T210 222 T310 222 T390 222", "fill": false}, {"t": "path", "d": "M10 222 L10 250 L390 250 L390 222", "fill": false}], "anchor": [200, 236]}, {"id": "sun", "label": "Sun", "say": "The sun heats the water.", "color": "#ffd29e", "box": [318, 24, 64, 64], "shapes": [{"t": "sun", "x": 350, "y": 56, "r": 20}], "anchor": [350, 56]}, {"id": "evap", "label": "Evaporation", "say": "Warm water turns into vapour and rises.", "color": "#8fe0b0", "box": [100, 110, 70, 96], "shapes": [{"t": "arrow", "x1": 112, "y1": 204, "x2": 112, "y2": 116}, {"t": "arrow", "x1": 136, "y1": 204, "x2": 136, "y2": 116}, {"t": "arrow", "x1": 160, "y1": 204, "x2": 160, "y2": 116}], "anchor": [136, 160]}, {"id": "cloud", "label": "Condensation", "say": "High up the vapour cools into tiny drops: clouds.", "color": "#a3a3ad", "box": [150, 40, 124, 48], "shapes": [{"t": "cloud", "kind": "white", "x": 210, "y": 64, "w": 118}], "anchor": [210, 66]}, {"id": "rain", "label": "Precipitation", "say": "When the drops get heavy they fall as rain.", "color": "#7ee0e0", "box": [176, 92, 80, 40], "shapes": [{"t": "drops", "x": 214, "y": 102, "w": 64}], "anchor": [214, 108]}, {"id": "runoff", "label": "Runoff", "say": "Rain runs down the land back to the sea.", "color": "#c9a7ff", "box": [240, 140, 140, 82], "shapes": [{"t": "path", "d": "M244 220 L300 148 L372 220"}, {"t": "tree", "kind": "pine", "x": 300, "y": 152, "h": 34}, {"t": "grass", "x": 340, "y": 212, "w": 34}, {"t": "arrow", "x1": 326, "y1": 190, "x2": 272, "y2": 216}], "anchor": [330, 190]}], "next": ["Why does the water vapour cool into clouds?", "Where does the rain go after it falls?"]},
