    '2d': {"title": "How photosynthesis works", "mode": "2d", "layout": "a leaf in the middle on its stem; the sun top left; CO2 coming in from the left; water rising from the roots; O2 leaving top right; glucose bottom right", "intro": "A leaf makes its own food from light, air and water.", "summary": "Light, carbon dioxide and water make glucose and release oxygen in the chloroplast.", "photo": "a real green leaf on a plant in bright sunlight, close up, showing its veins", "parts": [{"id": "sun", "label": "Sunlight", "say": "Sunlight gives the leaf the energy it needs.", "color": "#ffd29e", "box": [30, 30, 126, 78], "anchor": [54, 54], "shapes": [{"t": "sun", "x": 52, "y": 52, "r": 17}, {"t": "arrow", "x1": 76, "y1": 66, "x2": 152, "y2": 104}]}, {"id": "leaf", "label": "Leaf", "say": "The leaf is a thin green blade with veins that carry water and food.", "color": "#8fe0b0", "box": [136, 70, 200, 170], "anchor": [214, 170], "shapes": [{"t": "leaf", "kind": "oval", "x": 150, "y": 190, "h": 205, "rot": 58}, {"t": "line", "x1": 150, "y1": 190, "x2": 140, "y2": 236}]}, {"id": "chloro", "label": "Chloroplast", "say": "Inside the leaf cells, chloroplasts catch the light with green chlorophyll.", "color": "#7ee0e0", "box": [244, 108, 36, 24], "anchor": [262, 120], "shapes": [{"t": "ellipse", "cx": 262, "cy": 120, "rx": 16, "ry": 9, "fill": true}, {"t": "path", "d": "M251 117 L273 117"}, {"t": "path", "d": "M251 123 L273 123"}]}, {"id": "co2", "label": "Carbon dioxide in", "say": "Carbon dioxide from the air enters through tiny holes called stomata.", "color": "#a3a3ad", "box": [16, 130, 148, 40], "anchor": [90, 152], "shapes": [{"t": "text", "x": 20, "y": 142, "text": "CO2"}, {"t": "arrow", "x1": 20, "y1": 152, "x2": 160, "y2": 152}, {"t": "arrow", "x1": 20, "y1": 164, "x2": 154, "y2": 164}]}, {"id": "water", "label": "Water from roots", "say": "The roots take in water, and it travels up the stem to the leaf.", "color": "#7fb0ff", "box": [118, 196, 48, 60], "anchor": [147, 216], "shapes": [{"t": "path", "d": "M140 236 L124 252"}, {"t": "path", "d": "M140 236 L156 252"}, {"t": "path", "d": "M140 236 L140 254"}, {"t": "arrow", "x1": 147, "y1": 234, "x2": 147, "y2": 198}, {"t": "text", "x": 152, "y": 230, "text": "H2O"}]}, {"id": "o2", "label": "Oxygen out", "say": "Oxygen is made and leaves the leaf into the air.", "color": "#c9a7ff", "box": [296, 20, 92, 80], "anchor": [360, 34], "shapes": [{"t": "arrow", "x1": 300, "y1": 96, "x2": 352, "y2": 44}, {"t": "circle", "cx": 360, "cy": 34, "r": 6}, {"t": "circle", "cx": 374, "cy": 30, "r": 6}, {"t": "text", "x": 352, "y": 58, "text": "O2"}]}, {"id": "gluc", "label": "Glucose", "say": "Glucose, a sugar, is the food the plant makes and uses to grow.", "color": "#ffb067", "box": [268, 126, 100, 104], "anchor": [330, 193], "shapes": [{"t": "arrow", "x1": 270, "y1": 128, "x2": 318, "y2": 182}, {"t": "poly", "pts": [[318, 186], [330, 180], [342, 186], [342, 200], [330, 206], [318, 200], [318, 186]], "fill": true}, {"t": "text", "x": 296, "y": 226, "text": "C6H12O6"}]}], "next": ["What does the chloroplast do with the light?", "Why does the plant need carbon dioxide?"]},
