    '2d': {"title": "The parts of a tree", "mode": "2d", "layout": "the tree in the middle, standing on the ground at y 198; its roots spread in the soil below; the sun top left", "intro": "A tree is a plant with a strong woody trunk, held in the ground by its roots.", "summary": "Roots take in water, the trunk carries it up, the branches hold the leaves, and the leaves make the food.", "photo": "a real tall tree standing alone in a field, its trunk, branches and green leaves in sunlight", "parts": [{"id": "sun", "label": "Sunlight", "say": "The leaves need sunlight to make the tree's food.", "color": "#ffc93a", "box": [24, 16, 60, 60], "anchor": [52, 44], "shapes": [{"t": "sun", "x": 52, "y": 44, "r": 18}, {"t": "arrow", "x1": 76, "y1": 60, "x2": 122, "y2": 82}]}, {"id": "leaves", "label": "Leaves", "say": "The leaves catch the sunlight and make sugar from air and water: photosynthesis.", "color": "#4f9e3c", "box": [116, 16, 168, 182], "anchor": [234, 52], "shapes": [{"t": "tree", "kind": "oak", "x": 200, "y": 198, "h": 180}]}, {"id": "branches", "label": "Branches", "say": "Branches spread out from the trunk and hold the leaves up to the light.", "color": "#7a4b28", "box": [160, 88, 84, 44], "anchor": [176, 104], "shapes": [{"t": "path", "d": "M199 130 Q186 112 166 100"}, {"t": "path", "d": "M201 126 Q214 106 236 96"}, {"t": "path", "d": "M200 120 L200 96"}]}, {"id": "trunk", "label": "Trunk", "say": "The trunk holds the tree up and carries water up from the roots and food down from the leaves.", "color": "#7a4b28", "box": [184, 100, 32, 98], "anchor": [200, 168], "shapes": [{"t": "path", "d": "M186 198 C192 194 194 178 196 112"}, {"t": "path", "d": "M214 198 C208 194 206 178 204 112"}, {"t": "path", "d": "M199 186 Q201 160 198 136"}]}, {"id": "roots", "label": "Roots", "say": "The roots hold the tree in the ground and take in water and minerals from the soil.", "color": "#b07a4f", "box": [120, 196, 160, 60], "anchor": [168, 236], "shapes": [{"t": "rect", "x": 12, "y": 204, "w2": 376, "h": 52, "fill": true}, {"t": "path", "d": "M196 200 Q186 220 166 238"}, {"t": "path", "d": "M200 202 Q204 226 198 252"}, {"t": "path", "d": "M204 200 Q216 222 240 238"}, {"t": "path", "d": "M192 208 Q170 214 146 210"}, {"t": "path", "d": "M208 208 Q232 214 256 208"}]}], "next": ["How do roots take in water?", "How do leaves make the tree's food?"]},
    '3d': {"title": "The parts of a tree", "mode": "3d", "axis": "y", "intro": "A tree stands on its roots in the soil; the trunk holds it up, the branches spread out, and the leaves catch the light.", "summary": "Roots take in water, the trunk carries it up, the branches hold the leaves, and the leaves make the food.", "photo": "a real tall tree standing alone in a field, its trunk, branches and green leaves in sunlight", "next": ["How do roots take in water?", "How do leaves make the tree's food?"], "parts": [{"id": "leaves", "label": "Leaves", "say": "The leaves catch the sunlight and make sugar from air and water: photosynthesis.", "color": "#4f8f36", "shapes": [{"t": "tree", "kind": "oak", "only": "crown", "pos": [0, 0, 0], "h": 4}], "size": 0.6, "inside": null}, {"id": "branches", "label": "Branches", "say": "Branches spread out from the trunk and hold the leaves up to the light.", "color": "#6b4a30", "shapes": [{"t": "tree", "kind": "oak", "only": "branches", "pos": [0, 0, 0], "h": 4}], "size": 0.7, "inside": null}, {"id": "trunk", "label": "Trunk", "say": "The trunk holds the tree up and carries water up from the roots and food down from the leaves.", "color": "#6b4a30", "shapes": [{"t": "tree", "kind": "oak", "only": "trunk", "pos": [0, 0, 0], "h": 4}], "size": 0.5, "inside": null}, {"id": "roots", "label": "Roots", "say": "The roots spread under the ground, hold the tree in place and take in water and minerals.", "color": "#8a6142", "shapes": [{"t": "tree", "kind": "oak", "only": "roots", "pos": [0, 0, 0], "h": 4}], "size": 0.4, "inside": "soil"}, {"id": "soil", "label": "Soil", "say": "The soil holds the water and minerals the roots take in.", "color": "#7a5436", "shapes": [{"t": "ground", "kind": "soil", "pos": [0, 0, 0], "w": 2.6}], "size": 0.6, "inside": null}, {"id": "sun", "label": "Sunlight", "say": "The leaves need sunlight to make the tree's food.", "color": "#ffcf3d", "shapes": [{"t": "sun", "pos": [-2.4, 4.4, -1], "r": 0.4}], "size": 0.1, "inside": null}]},
