    '2d': {"title": "The parts of a flower", "mode": "2d", "layout": "one big lily in the middle on its stem; the pistil and stamens in its centre; the sepals under the petals; leaves on the stem", "intro": "A flower is the part of a plant that makes seeds.", "summary": "Stamens make pollen, the pistil catches it, and the ovary grows the seeds.", "photo": "a real white and pink lily flower, close up, showing its petals, stamens and pistil", "parts": [{"id": "petals", "label": "Petals", "say": "The bright petals attract bees and butterflies to the flower.", "color": "#e79ab5", "box": [117, 20, 166, 230], "anchor": [246, 70], "shapes": [{"t": "flower", "kind": "lily", "x": 200, "y": 250, "h": 230}]}, {"id": "stamen", "label": "Stamens", "say": "Stamens make pollen: a thin filament holds up the anther at its tip.", "color": "#d39a2c", "box": [174, 46, 52, 40], "anchor": [176, 60], "shapes": [{"t": "path", "d": "M200 84 Q188 70 178 58"}, {"t": "path", "d": "M200 84 Q212 70 222 58"}, {"t": "ellipse", "cx": 177, "cy": 56, "rx": 5, "ry": 3, "fill": true}, {"t": "ellipse", "cx": 223, "cy": 56, "rx": 5, "ry": 3, "fill": true}]}, {"id": "pistil", "label": "Pistil (stigma)", "say": "The pistil is in the middle; its sticky top, the stigma, catches the pollen.", "color": "#6aa64a", "box": [192, 30, 16, 56], "anchor": [200, 38], "shapes": [{"t": "path", "d": "M200 92 L200 42"}, {"t": "circle", "cx": 200, "cy": 38, "r": 5, "fill": true}]}, {"id": "ovary", "label": "Ovary", "say": "At the base of the pistil, the ovary holds the ovules that become seeds.", "color": "#4d8f3a", "box": [188, 88, 24, 22], "anchor": [200, 98], "shapes": [{"t": "ellipse", "cx": 200, "cy": 98, "rx": 9, "ry": 8, "fill": true}, {"t": "path", "d": "M195 98 L205 98"}]}, {"id": "sepal", "label": "Sepals", "say": "Green sepals wrapped the bud before it opened, and now hold the flower.", "color": "#5f9a46", "box": [180, 104, 40, 20], "anchor": [186, 114], "shapes": [{"t": "path", "d": "M200 110 Q186 108 180 118 Q192 118 200 112 Z", "fill": true}, {"t": "path", "d": "M200 110 Q214 108 220 118 Q208 118 200 112 Z", "fill": true}]}, {"id": "stem", "label": "Stem", "say": "The stem holds the flower up and carries water to it.", "color": "#5f9a46", "box": [190, 118, 20, 132], "anchor": [200, 156], "shapes": [{"t": "path", "d": "M199 248 C197 200 202 160 200 118"}, {"t": "path", "d": "M201 222 L203 176"}]}], "next": ["How does pollen get from one flower to another?", "How does a flower become a fruit?"]},
