    '2d': {"title": "Kinds of weather", "mode": "2d", "layout": "six kinds of weather in two rows of three: sunny, cloudy, rainy on top; stormy, snowy, a rainbow below", "intro": "Weather is what the air is like at a place and time: hot or cold, wet or dry, calm or windy.", "summary": "The sun's heat, the water in the air and the wind make every kind of weather.", "photo": "a real sky with the sun, white clouds and a rainbow after rain", "parts": [{"id": "sunny", "label": "Sunny", "say": "A clear sky: the sun warms the ground and the air.", "color": "#ffc93a", "box": [30, 18, 80, 80], "anchor": [70, 56], "shapes": [{"t": "sun", "x": 70, "y": 56, "r": 24}]}, {"id": "cloudy", "label": "Cloudy", "say": "Clouds are tiny water drops in the air, so thick they hide the sun.", "color": "#a9b4c6", "box": [150, 30, 100, 56], "anchor": [200, 58], "shapes": [{"t": "cloud", "kind": "white", "x": 200, "y": 60, "w": 96}, {"t": "cloud", "kind": "grey", "x": 226, "y": 74, "w": 60}]}, {"id": "rainy", "label": "Rainy", "say": "When the drops in a cloud grow heavy, they fall as rain.", "color": "#4aa3e8", "box": [282, 26, 100, 90], "anchor": [332, 58], "shapes": [{"t": "cloud", "kind": "rain", "x": 332, "y": 54, "w": 92}]}, {"id": "stormy", "label": "Stormy", "say": "A thunderstorm: tall dark clouds, heavy rain, lightning and thunder.", "color": "#8b97b3", "box": [20, 140, 100, 100], "anchor": [70, 168], "shapes": [{"t": "cloud", "kind": "storm", "x": 70, "y": 166, "w": 92}]}, {"id": "snowy", "label": "Snowy", "say": "When the air is cold enough, the water in clouds freezes into snowflakes.", "color": "#8ec3f2", "box": [150, 140, 100, 100], "anchor": [200, 168], "shapes": [{"t": "cloud", "kind": "snow", "x": 200, "y": 166, "w": 92}]}, {"id": "rainbow", "label": "Rainbow", "say": "After rain, sunlight shines through the drops and splits into seven colours.", "color": "#5cc36a", "box": [282, 150, 100, 70], "anchor": [332, 176], "shapes": [{"t": "rainbow", "x": 332, "y": 214, "r": 48}]}], "next": ["How do clouds form?", "Why does it thunder?"]},
